import adapter from "@sveltejs/adapter-cloudflare";
import devPlugin from "#lib/server/plugins/dev/index.js";
import svxPlugin from "#lib/server/plugins/svx/index.js";
import { sveltekit } from "@sveltejs/kit/vite";
import { defineConfig } from "vite";

export default defineConfig(() => {
	return {
		plugins: [
			// Point registry links at the local DOMAIN_URL on dev
			devPlugin(),
			svxPlugin(),
			sveltekit({
				adapter: adapter(),
				extensions: [".svelte", ".svx"],
				compilerOptions: {
					// Force runes mode for the project, except for libraries. Can be removed in svelte 6.
					runes: ({ filename }) => (filename.split(/[/\\]/).includes("node_modules") ? undefined : true),
					warningFilter: (warning) => (warning.code === "state_referenced_locally" ? false : true),
				},
			}),
		],
	};
});

import type { LayoutServerLoad } from "./$types";

// When using the static adapter ? set to true : set to false to remove dark mode flash since we set dark class inside hook
export const prerender = false;

export const load: LayoutServerLoad = async (event) => {
	const userData = event.locals.userData;
	const isDarkMode = event.locals.isDarkMode;
	const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(event.request.headers.get("user-agent") || "");
	event.depends("layout");
	return { isMobile, isDarkMode, userData };
};
